def value_card_sales_were_logged_as_products(apps, schema_editor):
    """A value-card sale used to be written to the commission log as 'Product'.
    Re-label those rows (same bill, same line name) so past reports agree with
    new ones."""
    ServiceLog = apps.get_model('staff', 'ServiceLog')
    InvoiceItem = apps.get_model('billing', 'InvoiceItem')
    card_lines = InvoiceItem.objects.filter(content_type__app_label='marketing',
                                            content_type__model='valuecard')
    pairs = {(row['invoice_id'], (row['description'] or '')[:255])
             for row in card_lines.values('invoice_id', 'description')}
    if not pairs:
        return
    invoice_ids = {invoice_id for invoice_id, _ in pairs}
    for log in ServiceLog._base_manager.filter(service_type='Product', invoice_id__in=invoice_ids):
        if (log.invoice_id, log.service_name) in pairs:
            log.service_type = 'Value Card'
            log.save(update_fields=['service_type'])


